package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API67 generator closure contracts admitted in Wave44b.
func TestRunJSONGeneratorClosureContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonGeneratorObserve67.cls"), "@IsTest private class GladeJsonGeneratorObserve67 {\nprivate static void finish(List<Object> rows,Integer expected){System.assertEquals(expected,rows.size(),'Every supplemental operation retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Supplemental observation exceeds bound');}\nprivate static Map<String,Object> phase(String scenario,String operation,String phaseName){return new Map<String,Object>{'scenario'=>scenario,'operation'=>operation,'phase'=>phaseName};}\nprivate static void error(Map<String,Object> row,Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}\nprivate static void one(List<Object> rows,String scenario,Boolean closeFirst,Integer stopAfter){\nString operation=closeFirst?'close':'getAsString';\nJSONGenerator gen=JSON.createGenerator(false);\nMap<String,Object> row=phase(scenario,operation,'build');\ntry{\nif(scenario=='object'){gen.writeStartObject();}\nelse if(scenario=='array'){gen.writeStartArray();gen.writeNumber(7);}\nelse if(scenario=='nested'){gen.writeStartObject();gen.writeFieldName('items');gen.writeStartArray();gen.writeStartObject();gen.writeStringField('name','owned');}\nelse if(scenario=='pending-field'){gen.writeStartObject();gen.writeFieldName('unfinished');}\nrow.put('returned',true);\n}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedBefore');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'finish');\ntry{if(closeFirst){gen.close();row.put('returned',true);}else{row.put('value',gen.getAsString());}}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedAfter');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'readAfter');try{row.put('value',gen.getAsString());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedAfterRead');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'writeAfter');try{gen.writeString('after');row.put('returned',true);}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'closedAfterWrite');try{row.put('value',gen.isClosed());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\nrow=phase(scenario,operation,'readAfterWrite');try{row.put('value',gen.getAsString());}catch(Exception e){error(row,e);}rows.add(row);if(rows.size()==stopAfter)return;\n}\n@IsTest static void string_object_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'object',false,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'getAsString','phase'=>'build','returned'=>true,'scenario'=>'object'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedBefore','scenario'=>'object','value'=>false},new Map<String,Object>{'operation'=>'getAsString','phase'=>'finish','scenario'=>'object','value'=>'{}'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfter','scenario'=>'object','value'=>true},new Map<String,Object>{'operation'=>'getAsString','phase'=>'readAfter','scenario'=>'object','value'=>'{}'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfterRead','scenario'=>'object','value'=>true}});}\n@IsTest static void string_array_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'array',false,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'getAsString','phase'=>'build','returned'=>true,'scenario'=>'array'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedBefore','scenario'=>'array','value'=>false},new Map<String,Object>{'operation'=>'getAsString','phase'=>'finish','scenario'=>'array','value'=>'[7]'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfter','scenario'=>'array','value'=>true},new Map<String,Object>{'operation'=>'getAsString','phase'=>'readAfter','scenario'=>'array','value'=>'[7]'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfterRead','scenario'=>'array','value'=>true}});}\n@IsTest static void close_object_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'object',true,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'close','phase'=>'build','returned'=>true,'scenario'=>'object'},new Map<String,Object>{'operation'=>'close','phase'=>'closedBefore','scenario'=>'object','value'=>false},new Map<String,Object>{'operation'=>'close','phase'=>'finish','returned'=>true,'scenario'=>'object'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfter','scenario'=>'object','value'=>true},new Map<String,Object>{'operation'=>'close','phase'=>'readAfter','scenario'=>'object','value'=>'{}'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfterRead','scenario'=>'object','value'=>true}});}\n@IsTest static void close_array_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'array',true,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'close','phase'=>'build','returned'=>true,'scenario'=>'array'},new Map<String,Object>{'operation'=>'close','phase'=>'closedBefore','scenario'=>'array','value'=>false},new Map<String,Object>{'operation'=>'close','phase'=>'finish','returned'=>true,'scenario'=>'array'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfter','scenario'=>'array','value'=>true},new Map<String,Object>{'operation'=>'close','phase'=>'readAfter','scenario'=>'array','value'=>'[7]'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfterRead','scenario'=>'array','value'=>true}});}\n@IsTest static void string_nested_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'nested',false,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'getAsString','phase'=>'build','returned'=>true,'scenario'=>'nested'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedBefore','scenario'=>'nested','value'=>false},new Map<String,Object>{'operation'=>'getAsString','phase'=>'finish','scenario'=>'nested','value'=>'{\"items\":[{\"name\":\"owned\"}]}'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfter','scenario'=>'nested','value'=>true},new Map<String,Object>{'operation'=>'getAsString','phase'=>'readAfter','scenario'=>'nested','value'=>'{\"items\":[{\"name\":\"owned\"}]}'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfterRead','scenario'=>'nested','value'=>true}});}\n@IsTest static void string_pending_field_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'pending-field',false,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'getAsString','phase'=>'build','returned'=>true,'scenario'=>'pending-field'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedBefore','scenario'=>'pending-field','value'=>false},new Map<String,Object>{'operation'=>'getAsString','phase'=>'finish','scenario'=>'pending-field','value'=>'{\"unfinished\"}'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfter','scenario'=>'pending-field','value'=>true},new Map<String,Object>{'operation'=>'getAsString','phase'=>'readAfter','scenario'=>'pending-field','value'=>'{\"unfinished\"}'},new Map<String,Object>{'operation'=>'getAsString','phase'=>'closedAfterRead','scenario'=>'pending-field','value'=>true}});}\n@IsTest static void close_nested_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'nested',true,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'close','phase'=>'build','returned'=>true,'scenario'=>'nested'},new Map<String,Object>{'operation'=>'close','phase'=>'closedBefore','scenario'=>'nested','value'=>false},new Map<String,Object>{'operation'=>'close','phase'=>'finish','returned'=>true,'scenario'=>'nested'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfter','scenario'=>'nested','value'=>true},new Map<String,Object>{'operation'=>'close','phase'=>'readAfter','scenario'=>'nested','value'=>'{\"items\":[{\"name\":\"owned\"}]}'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfterRead','scenario'=>'nested','value'=>true}});}\n@IsTest static void close_pending_field_closedAfterRead(){List<Object> rows=new List<Object>();one(rows,'pending-field',true,6);finish(rows,6);assertRows(rows,new List<Object>{new Map<String,Object>{'operation'=>'close','phase'=>'build','returned'=>true,'scenario'=>'pending-field'},new Map<String,Object>{'operation'=>'close','phase'=>'closedBefore','scenario'=>'pending-field','value'=>false},new Map<String,Object>{'operation'=>'close','phase'=>'finish','returned'=>true,'scenario'=>'pending-field'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfter','scenario'=>'pending-field','value'=>true},new Map<String,Object>{'operation'=>'close','phase'=>'readAfter','scenario'=>'pending-field','value'=>'{\"unfinished\"}'},new Map<String,Object>{'operation'=>'close','phase'=>'closedAfterRead','scenario'=>'pending-field','value'=>true}});}\nprivate static void assertRows(List<Object> rows,List<Object> expectedRows){System.assertEquals(expectedRows.size(),rows.size(),'Exact observed population');for(Integer i=0;i<rows.size();i++){Map<String,Object> actual=(Map<String,Object>)rows[i];Map<String,Object> expected=(Map<String,Object>)expectedRows[i];System.assertEquals(expected.keySet(),actual.keySet(),'Exact observed fields');for(String key:expected.keySet())System.assertEquals(expected.get(key),actual.get(key),'Observed row '+i+' field '+key);}}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJsonGeneratorObserve67.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 8 || got.Passed != 8 || got.Failed != 0 || got.Skipped != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact generator closure contracts failed: %s", data)
	}
}
